create or replace function public.delete_my_account() returns void language plpgsql security definer set search_path = '' as $$ declare uid uuid := auth.uid(); begin if uid is null then raise exception 'not authenticated' using errcode = '28000'; end if; delete from public.achievements where user_id = uid; delete from public.knowledge_recommendations where user_id = uid; delete from public.lesson_ratings where user_id = uid; delete from public.lesson_registrations where user_id = uid; delete from public.mke_notification_jobs where user_id = uid; delete from public.search_analytics_events where user_id = uid; delete from public.study_sessions where user_id = uid; delete from public.user_search_preferences where user_id = uid; delete from public.governance_user_roles where user_id = uid; delete from public.client_error_logs where user_id = uid::text; delete from public.open_api_keys where owner_id = uid::text; delete from public.open_webhooks where owner_id = uid::text; update public.sheikhs set profile_id = null where profile_id = uid; delete from auth.users where id = uid; end $$; revoke all on function public.delete_my_account() from public, anon; grant execute on function public.delete_my_account() to authenticated;
